// src/Socket.jsx
import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

export default function Socket({ currentUser }) {
  const [allUsers, setAllUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [chatMessages, setChatMessages] = useState([]);
  const [message, setMessage] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    if (!currentUser) return;

    socket.emit("set username", currentUser);

    socket.on("all users", (users) => {
      const filtered = users.filter((u) => u.username !== currentUser);
      setAllUsers(filtered);
    });

    socket.on("load messages", (msgs) => {
      setChatMessages(msgs);
    });

    socket.on("private message", (msg) => {
      setChatMessages((prev) => [...prev, msg]);
    });

    return () => {
      socket.off("all users");
      socket.off("load messages");
      socket.off("private message");
    };
  }, [currentUser]);

  const sendMessage = (e) => {
    e.preventDefault();
    if (!message || !selectedUser) return;

    const msg = {
      from: currentUser,
      to: selectedUser,
      content: message,
      timestamp: new Date(),
    };

    socket.emit("private message", msg);
    setMessage("");
  };

  const filteredUsers = allUsers.filter((user) =>
    user.username.toLowerCase().includes(search.toLowerCase())
  );

  const filteredMessages = chatMessages.filter(
    (m) =>
      (m.from === currentUser && m.to === selectedUser) ||
      (m.from === selectedUser && m.to === currentUser)
  );

  return (
    <div style={styles.container}>
      <div style={styles.sidebar}>
        <h2 style={styles.header}>💬 Messenger</h2>
        <input
          type="text"
          placeholder="🔍 Search users..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={styles.searchInput}
        />
        <div style={styles.userList}>
          {filteredUsers.length === 0 ? (
            <div style={styles.noUser}>No users found</div>
          ) : (
            filteredUsers.map((user) => (
              <div
                key={user.username}
                style={{
                  ...styles.userItem,
                  backgroundColor:
                    selectedUser === user.username ? "#e0e0ff" : "transparent",
                }}
                onClick={() => setSelectedUser(user.username)}
              >
                <span style={styles.statusIcon}>
                  {user.online ? "🟢" : "⚪"}
                </span>
                <span>{user.username}</span>
              </div>
            ))
          )}
        </div>
      </div>

      <div style={styles.chatPanel}>
        {selectedUser ? (
          <>
            <div style={styles.chatHeader}>
              Chatting with <strong>{selectedUser}</strong>
            </div>
            <div style={styles.chatBox}>
              {filteredMessages.map((msg, idx) => (
                <div
                  key={idx}
                  style={{
                    ...styles.message,
                    alignSelf:
                      msg.from === currentUser ? "flex-end" : "flex-start",
                    backgroundColor:
                      msg.from === currentUser ? "#daf5dc" : "#f0f0f0",
                  }}
                >
                  <span>
                    <strong>
                      {msg.from === currentUser ? "You" : msg.from}
                    </strong>
                    : {msg.content}
                  </span>
                </div>
              ))}
            </div>
            <form onSubmit={sendMessage} style={styles.inputArea}>
              <input
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Type a message..."
                style={styles.messageInput}
              />
              <button type="submit" style={styles.sendButton}>
                ➤
              </button>
            </form>
          </>
        ) : (
          <div style={styles.noChat}>
            👈 Select a user to start chatting!
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    height: "100vh",
    fontFamily: "Arial, sans-serif",
    backgroundColor: "#f8f9fa",
  },
  sidebar: {
    width: "250px",
    borderRight: "1px solid #ddd",
    padding: "20px",
    backgroundColor: "#fff",
    display: "flex",
    flexDirection: "column",
  },
  header: {
    fontSize: "20px",
    marginBottom: "10px",
    textAlign: "center",
    color: "#333",
  },
  searchInput: {
    padding: "8px",
    borderRadius: "5px",
    border: "1px solid #ccc",
    marginBottom: "10px",
  },
  userList: {
    flex: 1,
    overflowY: "auto",
  },
  userItem: {
    display: "flex",
    alignItems: "center",
    gap: "8px",
    padding: "10px",
    cursor: "pointer",
    borderRadius: "5px",
    transition: "background 0.2s",
  },
  statusIcon: {
    fontSize: "10px",
  },
  noUser: {
    textAlign: "center",
    color: "#999",
    marginTop: "20px",
  },
  chatPanel: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    padding: "20px",
    backgroundColor: "#f5f7fb",
  },
  chatHeader: {
    marginBottom: "10px",
    fontWeight: "bold",
    color: "#444",
  },
  chatBox: {
    flex: 1,
    overflowY: "auto",
    display: "flex",
    flexDirection: "column",
    gap: "8px",
    padding: "10px",
    borderRadius: "5px",
    backgroundColor: "#fff",
    border: "1px solid #ddd",
  },
  message: {
    padding: "10px",
    borderRadius: "12px",
    maxWidth: "60%",
    wordWrap: "break-word",
  },
  inputArea: {
    display: "flex",
    marginTop: "10px",
  },
  messageInput: {
    flex: 1,
    padding: "10px",
    borderRadius: "5px",
    border: "1px solid #ccc",
    marginRight: "10px",
  },
  sendButton: {
    padding: "10px 20px",
    backgroundColor: "#4a90e2",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },
  noChat: {
    margin: "auto",
    fontSize: "18px",
    color: "#999",
  },
};
